const payload = $json.body || $json;
const query = ((payload.query || payload.message || '').toString() || '').trim();
const language = ((payload.language || 'es').toString().toLowerCase() === 'en') ? 'en' : 'es';
return [{
  json: {
    workflow_execution_id: $execution.id,
    query: query,
    queryNormalized: query.toLowerCase(),
    service: (payload.service || payload.category || 'general').toString(),
    language: language,
    session_id: (payload.session_id || '').toString(),
    customer_id: (payload.customer_id || '').toString(),
    channel: (payload.channel || 'web').toString(),
    intent: (payload.intent || payload.current_intent || 'SERVICE_INFORMATION').toString(),
    selected_tool: (payload.selected_tool || payload.tool || 'KB_SEARCH').toString(),
    conversation_stage: (payload.conversation_stage || '').toString(),
    useRemote: ((payload.kb_api_url || payload.kbApiUrl || payload.config?.kb_api_url || '').toString().trim().length > 4)
  }
}];

const catalog = [
  { id: 'kb_credit_services', topic: 'services', language: 'es', title: 'Servicios de crédito', content: 'Atendemos servicios de credit education, credit repair assistance y credit improvement planning con enfoque educativo.' },
  { id: 'kb_tax_services', topic: 'services', language: 'es', title: 'Servicios de impuestos', content: 'Brindamos asistencia para preparación de impuestos: individual, self-employed y small business.' },
  { id: 'kb_business_formation', topic: 'services', language: 'es', title: 'Formación de negocio', content: 'Te guiamos en LLC formation, EIN assistance y documentación inicial.' },
  { id: 'kb_funding', topic: 'services', language: 'es', title: 'Financiamiento empresarial', content: 'Disponemos de apoyo para business funding, loan readiness y preparación de documentos.' },
  { id: 'kb_home', topic: 'services', language: 'es', title: 'Asistencia para vivienda', content: 'Te guiamos en programas USDA, FHA y Conventional y la preparación de documentos.' },
  { id: 'kb_pricing', topic: 'pricing', language: 'es', title: 'Precios', content: 'No se publican precios fijos para todos los casos; se confirman en consulta.' },
  { id: 'kb_appointments', topic: 'appointments', language: 'es', title: 'Citas', content: 'Validamos disponibilidad real, no confirmamos citas sin confirmación del calendario.' },
  { id: 'kb_language', topic: 'language', language: 'en', title: 'Language support', content: 'The bot supports Spanish and English responses based on customer language.' }
];

const base = $json;
const q = (base.queryNormalized || '').toLowerCase();
const terms = q.split(/\s+/).filter(Boolean);
const matches = catalog.filter((item) => {
  const content = `${item.topic} ${item.title} ${item.content}`.toLowerCase();
  if (item.language !== base.language && !(item.language === 'en' && base.language === 'es')) {
    return false;
  }
  return q.length === 0 || terms.some((t) => content.includes(t));
});

return [{
  json: {
    found: matches.length > 0,
    results: matches,
    confidence: matches.length > 0 ? 0.9 : 0,
    query: base.query,
    language: base.language,
    intent: base.intent,
    selected_tool: 'KB_SEARCH',
    tool: 'KB_SEARCH',
    service: base.service,
    session_id: base.session_id,
    customer_id: base.customer_id,
    channel: base.channel
  }
}];

const base = $json || {};
const source = base.body || base.data || base;
const response = (typeof source === 'object' && !Array.isArray(source)) ? source : {};

if (base.found !== undefined || response && response.results !== undefined) {
  return [{
    json: {
      found: Boolean(base.found ?? response.found ?? false),
      results: Array.isArray(base.results || response.results) ? (base.results || response.results) : [],
      confidence: Number(base.confidence || response.confidence || 0),
      query: base.query || response.query || '',
      language: base.language || response.language || 'es',
      intent: base.intent || response.intent || 'SERVICE_INFORMATION',
      selected_tool: base.selected_tool || response.selected_tool || response.tool || 'KB_SEARCH',
      tool: base.tool || response.tool || 'KB_SEARCH',
      service: base.service || response.service || 'general',
      session_id: base.session_id || response.session_id || '',
      customer_id: base.customer_id || response.customer_id || '',
      channel: base.channel || response.channel || 'web',
      raw: response
    }
  }];
}

return [{
  json: {
    found: false,
    results: [],
    confidence: 0,
    query: base.query || '',
    language: base.language || 'es',
    intent: base.intent || 'SERVICE_INFORMATION',
    selected_tool: 'KB_SEARCH',
    tool: 'KB_SEARCH',
    service: base.service || 'general',
    session_id: base.session_id || '',
    customer_id: base.customer_id || '',
    channel: base.channel || 'web',
    raw: base
  }
}];
